// Combine all analytics data
const jobStats = $('Get Job Discovery Stats').first().json;
const appStats = $('Get Application Stats').first().json;
const sourcePerf = $('Get Source Performance').all();
const skillDemand = $('Get Skill Demand Trends').all();
const salaryInsights = $('Get Salary Range Analysis').all();
const networkStats = $('Get Networking Stats').first().json;

// Calculate key metrics
const responseRate = appStats.applications_month > 0 
  ? ((appStats.interviews_month / appStats.applications_month) * 100).toFixed(2)
  : 0;

const weekOverWeekGrowth = jobStats.jobs_discovered_month > 0
  ? (((jobStats.jobs_discovered_week / (jobStats.jobs_discovered_month / 4)) - 1) * 100).toFixed(1)
  : 0;

const conversionRate = jobStats.jobs_discovered_month > 0
  ? ((appStats.applications_month / jobStats.jobs_discovered_month) * 100).toFixed(2)
  : 0;

const networkingROI = networkStats.total_contacts > 0
  ? ((networkStats.conversations_started / networkStats.total_contacts) * 100).toFixed(2)
  : 0;

return [{
  json: {
    period: 'week',
    generated_at: new Date().toISOString(),

    // Discovery metrics
    discovery: {
      jobs_this_week: jobStats.jobs_discovered_week,
      jobs_this_month: jobStats.jobs_discovered_month,
      high_quality_week: jobStats.high_score_jobs_week,
      high_quality_month: jobStats.high_score_jobs_month,
      avg_score: parseFloat(jobStats.avg_score || 0).toFixed(1),
      week_over_week_growth: weekOverWeekGrowth
    },

    // Application metrics
    applications: {
      submitted_week: appStats.applications_week,
      submitted_month: appStats.applications_month,
      interviews_total: appStats.interviews_total,
      interviews_month: appStats.interviews_month,
      rejections_week: appStats.rejections_week,
      response_rate: responseRate,
      conversion_rate: conversionRate,
      by_method: {
        linkedin: appStats.linkedin_apps,
        indeed: appStats.indeed_apps,
        manual: appStats.manual_apps
      }
    },

    // Source performance
    sources: sourcePerf.map(s => s.json),

    // Skill trends
    top_skills: skillDemand.slice(0, 10).map(s => s.json),

    // Salary insights
    salary_ranges: salaryInsights.map(s => s.json),

    // Networking metrics
    networking: {
      total_contacts: networkStats.total_contacts,
      connections_made: networkStats.connections_made,
      conversations: networkStats.conversations_started,
      contacts_this_week: networkStats.contacts_week,
      roi: networkingROI
    }
  }
}];

// Create dashboard data structure
const analytics = $('Combine All Analytics').first().json;
const aiReport = $input.first().json.response || $input.first().json.output;

const dashboardData = {
  generated_at: analytics.generated_at,
  period: 'weekly',

  // Summary cards
  summary: {
    jobs_discovered: analytics.discovery.jobs_this_week,
    applications_submitted: analytics.applications.submitted_week,
    interviews_scheduled: analytics.applications.interviews_month,
    response_rate: `${analytics.applications.response_rate}%`,
    avg_match_score: analytics.discovery.avg_score
  },

  // Charts data
  charts: {
    source_performance: analytics.sources.map(s => ({
      source: s.source,
      jobs: s.total_jobs,
      quality: s.high_quality_jobs,
      avg_score: parseFloat(s.avg_score).toFixed(1)
    })),

    skill_demand: analytics.top_skills.map(s => ({
      skill: s.skill,
      count: s.job_count,
      match: parseFloat(s.avg_match_score).toFixed(1)
    })),

    application_funnel: [
      { stage: 'Jobs Discovered', count: analytics.discovery.jobs_this_month },
      { stage: 'High Quality (70+)', count: analytics.discovery.high_quality_month },
      { stage: 'Applications Submitted', count: analytics.applications.submitted_month },
      { stage: 'Interview Requests', count: analytics.applications.interviews_month },
      { stage: 'Active Interviews', count: analytics.applications.interviews_total }
    ],

    weekly_trend: {
      jobs: analytics.discovery.jobs_this_week,
      applications: analytics.applications.submitted_week,
      growth: analytics.discovery.week_over_week_growth
    }
  },

  // Key metrics
  metrics: {
    conversion_rate: `${analytics.applications.conversion_rate}%`,
    response_rate: `${analytics.applications.response_rate}%`,
    networking_roi: `${analytics.networking.roi}%`,
    week_growth: `${analytics.discovery.week_over_week_growth}%`
  },

  // AI insights
  ai_analysis: aiReport,

  // Raw analytics for detailed views
  detailed_analytics: analytics
};

return [{ json: dashboardData }];

