// Generate optimization recommendations based on data
const analytics = $('Combine All Analytics').first().json;

const recommendations = [];

// Check response rate
if (parseFloat(analytics.applications.response_rate) < 2.0) {
  recommendations.push({
    priority: 'high',
    area: 'Application Quality',
    issue: `Response rate is ${analytics.applications.response_rate}% (target: 2-4%)`,
    action: 'Review and improve cover letter templates. Focus on personalization and company research.',
    impact: 'Could increase interview requests by 50-100%'
  });
}

// Check conversion rate
if (parseFloat(analytics.applications.conversion_rate) < 20) {
  recommendations.push({
    priority: 'medium',
    area: 'Application Volume',
    issue: `Only applying to ${analytics.applications.conversion_rate}% of discovered jobs`,
    action: 'Lower AI score threshold from 70 to 65, or approve more jobs in dashboard',
    impact: 'Could increase weekly applications by 20-30%'
  });
}

// Check source diversity
const sources = $('Get Source Performance').all();
if (sources.length < 3) {
  recommendations.push({
    priority: 'medium',
    area: 'Source Diversity',
    issue: 'Using fewer than 3 job sources',
    action: 'Add more job boards to workflow #1 (LinkedIn Jobs, Wellfound, AngelList)',
    impact: 'Could discover 30-50% more relevant jobs'
  });
}

// Check networking ROI
if (parseFloat(analytics.networking.roi) < 20) {
  recommendations.push({
    priority: 'low',
    area: 'Networking Effectiveness',
    issue: `Only ${analytics.networking.roi}% of contacts converting to conversations`,
    action: 'Improve LinkedIn message personalization. Reference specific posts or shared interests.',
    impact: 'Could double networking conversation rate'
  });
}

// Check weekly volume
if (analytics.applications.submitted_week < 50) {
  recommendations.push({
    priority: 'high',
    area: 'Application Pace',
    issue: `Only ${analytics.applications.submitted_week} applications this week (target: 50-100)`,
    action: 'Increase job approval rate and activate more application methods',
    impact: 'Critical for hitting 30-day goal of 325-400 applications'
  });
}

// Check score distribution
if (parseFloat(analytics.discovery.avg_score) < 60) {
  recommendations.push({
    priority: 'medium',
    area: 'Job Quality',
    issue: `Average job match score is ${analytics.discovery.avg_score} (low)`,
    action: 'Refine job search keywords in workflow #1 to better match your profile',
    impact: 'Better quality jobs = higher application success rate'
  });
}

return [{
  json: {
    recommendations: recommendations,
    total_recommendations: recommendations.length,
    high_priority: recommendations.filter(r => r.priority === 'high').length,
    generated_at: new Date().toISOString()
  }
}];

